package com.bridger.momentum;

import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Each named preset owns a template copy and a relative layout. */
public final class IslandPresets {
    private final Path folder;
    public IslandPresets(Path folder){this.folder=folder.toAbsolutePath().normalize();}
    public static IslandPresets local(){return new IslandPresets(Paths.get("config","bridgetap","island-presets"));}
    public static final class Preset{public final String name;public final IslandLayout layout;private final Path file,asset;private Preset(String name,IslandLayout layout,Path file,Path asset){this.name=name;this.layout=layout;this.file=file;this.asset=asset;}public IslandTemplate template()throws IOException{return IslandTemplate.read(asset);}}
    public List<Preset> list()throws IOException{Files.createDirectories(folder);List<Preset> result=new ArrayList<>();try(DirectoryStream<Path> files=Files.newDirectoryStream(folder,"*.properties")){for(Path file:files){if(result.size()>=500)break;try{String id=file.getFileName().toString().replace(".properties","");UUID.fromString(id);if(!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>65536)continue;Properties p=new Properties();try(InputStream in=Files.newInputStream(file)){p.load(in);}String version=p.getProperty("version","");if(!version.equals("1")&&!version.equals("2"))continue;String name=RunHistory.validName(p.getProperty("name",""));if(name.isEmpty())continue;Path asset=folder.resolve(id+".btisland");if(!Files.isRegularFile(asset,LinkOption.NOFOLLOW_LINKS))continue;IslandLayout layout=new IslandLayout(number(p,"x"),number(p,"y"),number(p,"z"),number(p,"sx"),number(p,"sy"),number(p,"sz"),number(p,"fx"),number(p,"fy"),number(p,"fz"),number(p,"rotation"),Boolean.parseBoolean(p.getProperty("focus","false")),version.equals("2"));result.add(new Preset(name,layout,file,asset));}catch(IllegalArgumentException ignored){}}}result.sort(Comparator.comparing(p->p.name,String.CASE_INSENSITIVE_ORDER));return result;}
    private static int number(Properties p,String key){return Integer.parseInt(p.getProperty(key,"0"));}
    public Preset save(String name,IslandTemplate template,IslandLayout layout)throws IOException{name=RunHistory.validName(name);if(name.isEmpty())throw new IOException("Enter a preset name");for(Preset old:list())if(old.name.equalsIgnoreCase(name))throw new IOException("A preset with that name already exists");String id=UUID.randomUUID().toString();Path asset=folder.resolve(id+".btisland"),file=folder.resolve(id+".properties"),temp=folder.resolve(id+".part");Properties p=new Properties();p.setProperty("version",layout.stableAnchor?"2":"1");p.setProperty("name",name);String[] keys={"x","y","z","sx","sy","sz","fx","fy","fz","rotation"};int[] values={layout.x,layout.y,layout.z,layout.startX,layout.startY,layout.startZ,layout.finishX,layout.finishY,layout.finishZ,layout.rotation};for(int i=0;i<keys.length;i++)p.setProperty(keys[i],String.valueOf(values[i]));p.setProperty("focus",String.valueOf(layout.focus));try{template.write(asset);try(OutputStream out=Files.newOutputStream(temp,StandardOpenOption.CREATE_NEW)){p.store(out,"BridgeTap island preset");}Files.move(temp,file);return new Preset(name,layout,file,asset);}catch(IOException ex){Files.deleteIfExists(asset);throw ex;}finally{Files.deleteIfExists(temp);}}
    public void delete(Preset preset)throws IOException{if(!preset.file.getParent().equals(folder)||!preset.asset.getParent().equals(folder))throw new IOException("Preset is outside this library");Files.deleteIfExists(preset.file);Files.deleteIfExists(preset.asset);}
}
